// 파일 책임: 화면 전체 진행 덮개. 등록소를 제공하고, 진행이 있으면 본문을 막고(inert·aria-busy) 가운데 진행 표시와 문구를 띄운다.
// 무엇이 진행 중인지는 등록(폼 저장·페이지 첫 조회)이, 문구는 프로젝트가 정한다. 덮개가 닫힐 때 잃은 포커스를 본문으로 돌린다
// (본문 DOM 안에서 마지막으로 포커스한 요소 → 사라졌으면 본문 첫 h1 → 그것도 없으면 본문 영역).
import type { ReactNode } from 'react';
import { FullPageProgressProvider, useFullPageProgressBinding } from '@boosterlab/web-kit/progress';
import { Spinner } from './pending';

/** 종류별 주 문구와 보조 문구(없으면 그리지 않음). */
export interface FullPageProgressMessages {
  readonly loading: string;
  readonly create: string;
  readonly edit: string;
  readonly delete: string;
  readonly wait?: string;
}

/**
 * 앱 셸에 한 번 두는 덮개. children(앱 본문)은 진행 중 inert·aria-busy가 되어 클릭·포커스·낭독에서 빠진다.
 * 대화창(portal)은 children 밖이라 덮개 위에서 조작된다. 덮개 층은 z-40으로 shadcn 대화창(z-50) 아래이며, 층·배경을 바꾸려면 이 복사본의 클래스를 고친다.
 * 상태 문구 영역(role=status)은 늘 있고 열릴 때 문구가 들어가 낭독기가 바뀜을 읽는다. 최소 표시 시간·지연은 없다.
 * `indicator`는 가운데 진행 표시를 프로젝트 모양으로 바꾼다(없으면 키트 원형 회전 표시). 덮개 전체가 낭독기에 숨겨져 있어(문구는 상태 영역이 읽는다) 표시는 그림만 맡고,
 * 움직임 줄이기 설정은 그 표시를 준 프로젝트가 맞춘다.
 */
export function FullPageProgress({
  messages,
  indicator,
  children,
}: {
  readonly messages: FullPageProgressMessages;
  readonly indicator?: ReactNode;
  readonly children: ReactNode;
}) {
  const binding = useFullPageProgressBinding();
  const { kind, open, contentRef, contentProps } = binding;
  return (
    <FullPageProgressProvider binding={binding}>
      <div ref={contentRef} data-slot="blocking-progress-root" {...contentProps}>
        {children}
      </div>
      {open ? (
        <div
          data-slot="blocking-progress"
          aria-hidden="true"
          className="fixed inset-0 z-40 flex items-center justify-center bg-background/80 backdrop-blur-xs"
        >
          <div
            data-slot="blocking-progress-box"
            className="flex flex-col items-center gap-6 text-center text-sm text-foreground"
          >
            {indicator === undefined ? <Spinner large /> : indicator}
            <div className="grid gap-1">
              <p>{messages[kind!]}</p>
              {messages.wait === undefined ? null : <p>{messages.wait}</p>}
            </div>
          </div>
        </div>
      ) : null}
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        data-slot="blocking-progress-status"
        className="sr-only"
      >
        {open
          ? [messages[kind!], messages.wait].filter((text) => text !== undefined).join(' ')
          : ''}
      </div>
    </FullPageProgressProvider>
  );
}

// @vitest-environment jsdom
// 파일 책임: 덮개 자체와 실제 함께 설치된 기능의 조합만 소비 복사본으로 검사한다.
import { FullPageProgress } from '../full-page-progress';
import { ConfirmDialog, DialogDefaults, defaultDialogLabels } from '../dialog';
import { checkProgressConformance } from '@boosterlab/web-kit/testing/unit/blocking-progress';
import type { checkFormProgressConformance as FormProgressCheck } from '@boosterlab/web-kit/testing/unit/combinations';
import installation from '../../../../../registry-installation.json';
const target = {
  registryVersion: installation.sourceRef,
  registryCommit: installation.sourceCommit,
};
checkProgressConformance(
  { FullPageProgress, ConfirmDialog, DialogDefaults, defaultDialogLabels },
  target
);
const names = new Set(installation.items.map((item) => item.name));
if (names.has('form')) {
  const forms = import.meta.glob('../form/form.tsx');
  const load = forms['../form/form.tsx'];
  if (!load) throw new Error('form 설치 기록에 맞는 소비 복사본 없음');
  type FormParts = Parameters<typeof FormProgressCheck>[0];
  const module = (await load()) as Pick<
    FormParts,
    'Form' | 'FormDefaults' | 'defaultFormMessages' | 'defaultFormGuardMessages'
  >;
  const { Form, FormDefaults, defaultFormMessages, defaultFormGuardMessages } = module;
  const { checkFormProgressConformance } =
    await import('@boosterlab/web-kit/testing/unit/combinations');
  await checkFormProgressConformance(
    {
      Form,
      FullPageProgress,
      FormDefaults,
      defaultFormMessages,
      defaultFormGuardMessages,
      DialogDefaults,
      defaultDialogLabels,
    },
    target
  );
}
if (names.has('list')) {
  const { checkListProgressConformance } =
    await import('@boosterlab/web-kit/testing/unit/combinations');
  await checkListProgressConformance({ FullPageProgress }, target);
}
if (names.has('record')) {
  const { checkRecordProgressConformance } =
    await import('@boosterlab/web-kit/testing/unit/combinations');
  await checkRecordProgressConformance({ FullPageProgress }, target);
}

// 파일 책임: 설치한 덮개·대화창과 선택적인 폼 복사본으로 브라우저 화면을 만든다.
import { createRoot } from 'react-dom/client';
import { createProgressFeatureConformancePage } from '@boosterlab/web-kit/testing/fixtures/progress';
import { FullPageProgress } from '../full-page-progress';
import { Dialog, DialogDefaults, defaultDialogLabels } from '../dialog';
import type { createFormProgressConformancePage as FormProgressPage } from '@boosterlab/web-kit/testing/fixtures/combinations';
import installation from '../../../../../registry-installation.json';
// 프로젝트 테마 CSS(components.json의 tailwind.css = src/styles.css)로 실제 화면과 같은 층·모양에서 검사한다. 위치가 다르면 이 import를 고친다.
import '@/styles.css';
let Page = createProgressFeatureConformancePage({
  FullPageProgress,
  Dialog,
  DialogDefaults,
  defaultDialogLabels,
});
if (
  new URLSearchParams(location.search).get('mode') === 'error' &&
  installation.items.some((item) => item.name === 'form')
) {
  const forms = import.meta.glob('../form/form.tsx');
  const load = forms['../form/form.tsx'];
  if (!load) throw new Error('form 설치 기록에 맞는 소비 복사본 없음');
  type FormParts = Parameters<typeof FormProgressPage>[0];
  const { Form, FormDefaults, defaultFormMessages, defaultFormGuardMessages } =
    (await load()) as Pick<
      FormParts,
      'Form' | 'FormDefaults' | 'defaultFormMessages' | 'defaultFormGuardMessages'
    >;
  const { createFormProgressConformancePage } =
    await import('@boosterlab/web-kit/testing/fixtures/combinations');
  Page = createFormProgressConformancePage({
    Form,
    FullPageProgress,
    FormDefaults,
    defaultFormMessages,
    defaultFormGuardMessages,
    DialogDefaults,
    defaultDialogLabels,
  });
}
createRoot(document.getElementById('root')!).render(<Page />);

// 파일 책임: 덮개 자체의 브라우저 검사와 설치한 폼 조합만 등록한다.
import {
  checkProgressFeatureBrowser,
  checkFormProgressBrowser,
} from '@boosterlab/web-kit/testing/browser';
import installation from '../../../registry-installation.json' with { type: 'json' };
const options = {
  url: '/web-kit-checks/blocking-progress.html',
  target: { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit },
};
checkProgressFeatureBrowser(options);
if (installation.items.some((item) => item.name === 'form')) checkFormProgressBrowser(options);
